+import { describe, it, expect, beforeEach } from 'vitest'
+import { GithubApi, InvalidIssueUrlError } from '../index.js'
+
+describe('parseIssueUrl', () => {
+  beforeEach(() => {
+    delete process.env.GITHUB_HOSTS
+  })
+
+  it('accepts standard issue URL', () => {
+    const g = new GithubApi()
+    expect(g.parseIssueUrl('https://github.com/octocat/hello-world/issues/12')).toEqual({
+      host: 'github.com', owner: 'octocat', repo: 'hello-world', issueNumber: 12
+    })
+  })
+
+  it('accepts trailing slash', () => {
+    const g = new GithubApi()
+    expect(g.parseIssueUrl('https://github.com/o/r/issues/1/')).toEqual({ host: 'github.com', owner: 'o', repo: 'r', issueNumber: 1 })
+  })
+
+  it('accepts query and fragment', () => {
+    const g = new GithubApi()
+    expect(g.parseIssueUrl('https://github.com/o/r/issues/2?foo=1#bar')).toEqual({ host: 'github.com', owner: 'o', repo: 'r', issueNumber: 2 })
+  })
+
+  it('accepts www.github.com', () => {
+    const g = new GithubApi()
+    expect(g.parseIssueUrl('https://www.github.com/o/r/issues/3')).toEqual({ host: 'www.github.com', owner: 'o', repo: 'r', issueNumber: 3 })
+  })
+
+  it('accepts enterprise hosts from GITHUB_HOSTS', () => {
+    process.env.GITHUB_HOSTS = 'git.example.com'
+    const g = new GithubApi()
+    expect(g.parseIssueUrl('https://git.example.com/own/repo/issues/5')).toEqual({ host: 'git.example.com', owner: 'own', repo: 'repo', issueNumber: 5 })
+  })
+
+  it('rejects unknown hosts', () => {
+    const g = new GithubApi()
+    expect(() => g.parseIssueUrl('https://evil.com/o/r/issues/1')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects http protocol', () => {
+    const g = new GithubApi()
+    expect(() => g.parseIssueUrl('http://github.com/o/r/issues/1')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects pull request URLs', () => {
+    const g = new GithubApi()
+    expect(() => g.parseIssueUrl('https://github.com/o/r/pull/12')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects non-numeric issue numbers', () => {
+    const g = new GithubApi()
+    expect(() => g.parseIssueUrl('https://github.com/o/r/issues/abc')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects zero issue number', () => {
+    const g = new GithubApi()
+    expect(() => g.parseIssueUrl('https://github.com/o/r/issues/0')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects invalid owner/repo names', () => {
+    const g = new GithubApi()
+    expect(() => g.parseIssueUrl('https://github.com/Bad*Name/repo/issues/1')).toThrow(InvalidIssueUrlError)
+    expect(() => g.parseIssueUrl('https://github.com/owner/Bad#Repo/issues/1')).toThrow(InvalidIssueUrlError)
+  })
+})
