-        this.octokit = new Octokit({auth:this.token})
+        this.token = token ?? process.env.GITHUB_TOKEN ?? ''
+        // Octokit baseUrl for enterprise hosts will be set per-instance when parsing a URL.
+        this.octokit = new (Octokit as any)({auth:this.token})
+    }
+
+    private setupOctokitForHost(host: string) {
+        const isPublic = host === "github.com" || host === "www.github.com"
+        if (isPublic) {
+            this.octokit = new (Octokit as any)({ auth: this.token })
+        } else {
+            this.octokit = new (Octokit as any)({ auth: this.token, baseUrl: `https://${host}/api/v3` })
+        }
     }

-    parseIssueUrl(issueUrl:string){
-        const parts = issueUrl.replace("https://github.com/","").split("/")
-        return {
-            owner:parts[0] ?? "",
-            repo:parts[1] ?? "",
-            issueNumber:parseInt(parts[3] ?? "0")
+    parseIssueUrl(issueUrl:string): { host: string; owner: string; repo: string; issueNumber: number }{
+        // Accept only https URLs
+        let url: URL
+        try {
+            url = new URL(issueUrl)
+        } catch (err) {
+            throw new InvalidIssueUrlError("Invalid URL")
         }
+        if (url.protocol !== "https:") throw new InvalidIssueUrlError("Only https:// URLs are supported")
+
+        const host = url.hostname.toLowerCase()
+        const allowedHosts = ["github.com", "www.github.com"]
+        const envHosts = (process.env.GITHUB_HOSTS || "").split(",").map(s=>s.trim()).filter(Boolean)
+        const allHosts = allowedHosts.concat(envHosts)
+        if (!allHosts.includes(host)) throw new InvalidIssueUrlError("Unknown host")
+
+        // path: /owner/repo/issues/123
+        const parts = url.pathname.split("/").filter(Boolean)
+        if (parts.length < 4) throw new InvalidIssueUrlError("Invalid issue URL path")
+        const owner = parts[0]!
+        const repo = parts[1]!
+        const kind = parts[2]!
+        const numberStr = parts[3]!
+
+        if (kind === "pull" || /pulls?/.test(kind)) throw new InvalidIssueUrlError("Pull request URLs are not accepted")
+        if (kind !== "issues") throw new InvalidIssueUrlError("URL must point to an issue")
+
+        // Validate owner/repo against a conservative GitHub-like pattern
+        const nameRe = /^[a-zA-Z0-9_.-]+$/
+        if (!nameRe.test(owner) || !nameRe.test(repo)) throw new InvalidIssueUrlError("Invalid owner or repository name")
+
+        const issueNumber = Number(numberStr)
+        if (!Number.isInteger(issueNumber) || issueNumber <= 0) throw new InvalidIssueUrlError("Invalid issue number")
+
+        return { host, owner, repo, issueNumber }
     }

     async getDefaultBranch(issueUrl: string): Promise<string> {
-        const { owner, repo } = this.parseIssueUrl(issueUrl)
+        const { host, owner, repo } = this.parseIssueUrl(issueUrl)
+        this.setupOctokitForHost(host)
         const { data } = await this.octokit.rest.repos.get({ owner, repo })
         return data.default_branch
     }

     async getIssue(issueUrl:string){
         try {
-            const {owner,repo,issueNumber} = this.parseIssueUrl(issueUrl)
+            const { host, owner,repo,issueNumber} = this.parseIssueUrl(issueUrl)
+            this.setupOctokitForHost(host)
             const {data} = await this.octokit.rest.issues.get({
                 owner,repo,issue_number:issueNumber
             })
@@ -42,7 +84,8 @@ export class GithubApi{

     async createBranch(issueUrl:string, branchName:string, baseBranch = "main"){
         try {
-            const {owner,repo} = this.parseIssueUrl(issueUrl)
+            const { host, owner,repo} = this.parseIssueUrl(issueUrl)
+            this.setupOctokitForHost(host)
             const {data:ref} = await this.octokit.rest.git.getRef({
                 owner,repo,ref:`heads/${baseBranch}`
             })
@@ -56,7 +99,8 @@ export class GithubApi{

     async openPR(issueUrl:string, branchName:string, baseBranch: string, title:string, body:string){
         try {
-            const {owner,repo} = this.parseIssueUrl(issueUrl)
+            const { host, owner,repo} = this.parseIssueUrl(issueUrl)
+            this.setupOctokitForHost(host)
             const {data} = await this.octokit.rest.pulls.create({
                 owner,repo,title,body,head:branchName,base:baseBranch
             })
